mapper.select:
  SELECT a.*
    FROM maven2_asset a
         INNER JOIN maven2_component c
         USING (component_id)
   WHERE a.repository_id = #{repositoryId}
     AND c.kind = 'maven-plugin'
     AND c.namespace = #{namespace}
     AND a.path LIKE '%.jar'
      AND asset_id > #{continuationToken}
ORDER BY asset_id
   LIMIT #{limit};
